insert into public.homepage_content(key,title,body,data) values
('intro','The Land of a Thousand Hills','Rwanda is a compact East African country of green hills, volcanoes, lakes and rainforest, known for mountain gorillas, remarkable cleanliness, warm hospitality and a rapidly growing tourism sector.','{}'),
('site_settings','Site settings',null,'{"site_name":"Visit Rwanda","contact_email":"","currency":"USD","default_cancellation_hours":48}'),
('travel_info','Travel information','Always confirm visa, health and entry rules with official Rwandan government sources before you travel.','{"items":[{"t":"Currency","d":"Rwandan franc (RWF)."},{"t":"Languages","d":"Kinyarwanda, English, French and Swahili."},{"t":"Best time","d":"Dry seasons: June to September and December to February."},{"t":"Electricity","d":"230V, plug types C and J."}]}')
